ControlPropertyState.AutoRuleBindingString:
UpdateIf(
    colSecurityBagSelectionState,
    true,
    {
        ReceivedBag: varSelectedReceiptBag,
        State: "Recibido-Seleccionado"
    }
);

If(
    CountRows(colMatchingDeclaredBags) = 0,
    Notify(
        "La bolsa no ha sido registrada por el cliente, favor confirmar si se desea proceder.",
        NotificationType.Error
    );

);
If(
    CountRows(colMatchingDeclaredBags) > 1,
    Notify("Se encontro mas de una tula registrada por el cliente con este numero, escoge la tula manualmente.");
    UpdateIf(
        colSecurityBagSelectionState,
        true,
        {State: "Declarado-Pendiente"}
    );

);
If(
    CountRows(colMatchingDeclaredBags) = 1,
    UpdateIf(
            colSecurityBagSelectionState,
            true,
            {
                DeclaredBag: First(colMatchingDeclaredBags),
                State: "Declarado-Seleccionado"
            }
        );
)

UpdateIf(
            colSecurityBagSelectionState,
            true,
            {
                DeclaredBag: varSelectedDeclaredBag,
                State: "Declarado-Seleccionado"
            }
);

UpdateIf(
    colSecurityBagSelectionState,
    true,
    {State: "Declarado-Seleccionado"}
);
Patch(
    'CH-Tbl-Bags',
    varSelectedReceiptBag,
    {
        BagStatus: 'BagStatus (CH-Tbl-Bags)'.'Asignada a cajero',
        RecountingSession: varRecountingSession
    }
);
Set(gvarSelectedTula, LookUp('CH-Tbl-Bags','CH-Tbl-Bags' = varSelectedReceiptBag.'CH-Tbl-Bags'));

ClearCollect(colSecurityBagSelectionState, {ID: Trim('txtinp NumeroTula_1'.Value), State: "Init", ReceivedBag:{}, DeclaredBag:{}});

Concurrent(
//Obtener todas las bolsas declaradas en exclusa. 
    ClearCollect(
        colMatchingReceivedBags,
        Filter(
            'CH-Tbl-Bags',
            BagID = First(colSecurityBagSelectionState).ID
        )
    ),
//Obtener bolsas declaradas con numero de bolsa igual a la escrita.
    ClearCollect(
        colMatchingDeclaredBags,
        Filter(
            'CH-Tbl-DeclaredBags',
            BagNumber = First(colSecurityBagSelectionState).ID
        )
    );
    ClearCollect(
        colMatchingDeclaredBags,
        Filter(
            colMatchingDeclaredBags,
            IsBlank(RecountedBag)
        )
    );

);
If(
    CountRows(colMatchingReceivedBags) = 0,
    Notify(
        "La bolsa no ha sido registrada en esclusa, no puede ser procesada.",
        NotificationType.Error
    );

);
If(
    CountRows(colMatchingReceivedBags) > 1,
    Notify("Se encontro mas de una tula registrada con este numero que aun no ha sido procesada, escoge la tula manualmente.");

);

If(
    CountRows(colMatchingReceivedBags) = 1,
    If(
        First(colMatchingReceivedBags).BagStatus = 'BagStatus (CH-Tbl-Bags)'.'Almacenada en boveda',
        Notify("Se ha encontrado una sola bolsa, se selecciona automaticamente.");
        UpdateIf(colSecurityBagSelectionState,true,{ReceivedBag:First(colMatchingReceivedBags), State: "Recibido-Seleccionado"});
        ,
        Notify(
            "No se pudo seleccionar automaticamente la unica bolsa registrada que se encontro, favor seleccionela manualmente",
            NotificationType.Warning
        );
        UpdateIf(colSecurityBagSelectionState,true,{ReceivedBag:First(colMatchingReceivedBags), State: "Recibido-Pendiente"});
    )
)

UpdateContext({varAddConfirm: true});
If(
    CountRows(
        Filter(
            'gal Checks'.AllItems,
            (!IsBlank(RelatedDeclaredCheck) && CheckboxCanvas1.Checked)
        )
    ) > 0,
    Notify(
        "Tienes seleccionado un cheque declarado. No puedes agregar un recuento con cheques declarado.",
        NotificationType.Error
    );
    UpdateContext({varAddConfirm: false});

);
If(
    CountRows(
        Filter(
            'gal Checks'.AllItems,
            IsBlank(RelatedDeclaredCheck)
            && (IsBlank(Trim(TextInputCanvas1_1.Value)) || IsBlank(DropdownCanvas2.Selected.Value) || IsBlank(NumberInput1.Value))
        )
    ) > 0,
    Notify(
        "Tiene un cheque con informacion incompleta.",
        NotificationType.Error
    );
    UpdateContext({varAddConfirm: false});

);
If(
    (Sum('gal Billetes'.AllItems,Value(lblTotal_1.Text)) + Sum('gal Monedas'.AllItems,Value(lblTotal_2.Text)) + Sum(Filter('gal Checks'.AllItems,(!IsBlank(RelatedDeclaredCheck) && CheckboxCanvas1.Checked) ||  IsBlank(RelatedDeclaredCheck)), Value(NumberInput1.Value) ) )<=0,
    Notify(
        "No hay ningun detalle que agregar.",
        NotificationType.Error
    );
    UpdateContext({varAddConfirm: false});

);

If(varAddConfirm, Notify("Agregar deposito", NotificationType.Success); UpdateContext({varDialogConfirmarAgregarDeposito: true}));

UpdateContext({varLinkConfirm: true});


If(
    varLinkConfirm,
    Notify(
        "Enlazar deposito",
        NotificationType.Success
    );
    UpdateContext({varDialogConfirmarEnlazarDeposito: true});
 ClearCollect(
        colNewDeposit,
        Defaults('CH-Tbl-DepositsRecountings')
    );
    Clear(colNewDeposit);
    NewForm(formRecountedDepositNew);
    Patch(
        colNewDeposit,
        If(IsBlank(varSelectedRecountedDeposit),  Defaults('CH-Tbl-DepositsRecountings'), varSelectedRecountedDeposit),
        {
            BagID: gvarSelectedTula,
            Currency: DropdownCanvas1.Selected.Value,
            BACLocalCheckAmount: Sum(
                Filter(
                    'gal Checks'.AllItems,
                    IsBlank(RelatedDeclaredCheck) && DropdownCanvas2.Selected.Value = 'CheckTypes (CH-Tbl-Checks)'.'BAC Local'
                ),
                Value(NumberInput1.Value)
            ),
            OtherLocaCheckAmount: Sum(
                Filter(
                    'gal Checks'.AllItems,
                    IsBlank(RelatedDeclaredCheck) && DropdownCanvas2.Selected.Value = 'CheckTypes (CH-Tbl-Checks)'.'Otros Local'
                ),
                Value(NumberInput1.Value)
            ),
            CashAmount: Value(Label6_55.Text)
        }
    );
    
);

UpdateContext({varAddConfirm: true});
If(
    CountRows(
        Filter(
            'gal Checks'.AllItems,
            (!IsBlank(RelatedDeclaredCheck) && CheckboxCanvas1.Checked)
        )
    ) > 0,
    Notify(
        "Tienes seleccionado un cheque declarado. No puedes agregar un recuento con cheques declarado.",
        NotificationType.Error
    );
    UpdateContext({varAddConfirm: false});

);
If(
    CountRows(
        Filter(
            'gal Checks'.AllItems,
            IsBlank(RelatedDeclaredCheck)
            && (IsBlank(Trim(TextInputCanvas1_1.Value)) || IsBlank(DropdownCanvas2.Selected.Value) || IsBlank(NumberInput1.Value))
        )
    ) > 0,
    Notify(
        "Tiene un cheque con informacion incompleta.",
        NotificationType.Error
    );
    UpdateContext({varAddConfirm: false});

);
If(
    (Sum('gal Billetes'.AllItems,Value(lblTotal_1.Text)) + Sum('gal Monedas'.AllItems,Value(lblTotal_2.Text)) + Sum(Filter('gal Checks'.AllItems,(!IsBlank(RelatedDeclaredCheck) && CheckboxCanvas1.Checked) ||  IsBlank(RelatedDeclaredCheck)), Value(NumberInput1.Value) ) )<=0,
    Notify(
        "No hay ningun detalle que agregar.",
        NotificationType.Error
    );
    UpdateContext({varAddConfirm: false});

);

If(varAddConfirm, Notify("Agregar deposito", NotificationType.Success); UpdateContext({varDialogConfirmarAgregarDeposito: true}));

If(
    Self.SelectedButton.Label = "Continuar",
    ClearCollect(colNewDeposit,Defaults('CH-Tbl-DepositsRecountings'));
    Clear(colNewDeposit);
    NewForm(formRecountedDeposit);
    Patch(
        colNewDeposit,
        Defaults('CH-Tbl-DepositsRecountings'),
        {
            BagID: gvarSelectedTula,
            Currency: DropdownCanvas1.Selected.Value,
            BACLocalCheckAmount: Sum(
                Filter(
                    'gal Checks'.AllItems,
                    IsBlank(RelatedDeclaredCheck) && DropdownCanvas2.Selected.Value = 'CheckTypes (CH-Tbl-Checks)'.'BAC Local'
                ),
                Value(lblTotal_2.Text)
            ),
            OtherLocaCheckAmount: Sum(
                Filter(
                    'gal Checks'.AllItems,
                    IsBlank(RelatedDeclaredCheck) && DropdownCanvas2.Selected.Value = 'CheckTypes (CH-Tbl-Checks)'.'Otros Local'
                ),
                Value(lblTotal_2.Text)
            ),
            CashAmount: Value(Label6_55.Text)
        }
    );
    SubmitForm(formRecountedDeposit);
);
UpdateContext({varDialogConfirmarAgregarDeposito: false});

If(
    Self.SelectedButton.Label = "Continuar",
    Clear(colRecountedMoneyDetails);
    Clear(colRecountedMoneyDetails);
    ForAll(
        Filter(
            colDefinedDenominations,
            Currency = DropdownCanvas1.Selected.Value
        ) As Denomination,
        Patch(
            colRecountedMoneyDetails,
            Defaults('CH-Tbl-CountedMoneyDetails'),
            {
                DenominationType: If(
                    Denomination.Type = 'Type (CH-Tbl-MoneyDenominations)'.Billete,
                    "Billete",
                    "Moneda"
                ),
                Quantity: 0,
                Denomination: Denomination.Value
            }
        );
    );
    RemoveIf(colChecks, IsBlank(RelatedDeclaredCheck));
    Reset('gal Checks');
);
UpdateContext({varDialogConfirmarCambioMoneda: false});

If(
    Self.SelectedButton.Label = "Continuar",
    ClearCollect(colNewDeposit,Defaults('CH-Tbl-DepositsRecountings'));
    Clear(colNewDeposit);
    NewForm(formRecountedDeposit);
    Patch(
        colNewDeposit,
        Defaults('CH-Tbl-DepositsRecountings'),
        {
            BagID: gvarSelectedTula,
            Currency: DropdownCanvas1.Selected.Value,
            BACLocalCheckAmount: Sum(
                Filter(
                    'gal Checks'.AllItems,
                    IsBlank(RelatedDeclaredCheck) && DropdownCanvas2.Selected.Value = 'CheckTypes (CH-Tbl-Checks)'.'BAC Local'
                ),
                Value(lblTotal_2.Text)
            ),
            OtherLocaCheckAmount: Sum(
                Filter(
                    'gal Checks'.AllItems,
                    IsBlank(RelatedDeclaredCheck) && DropdownCanvas2.Selected.Value = 'CheckTypes (CH-Tbl-Checks)'.'Otros Local'
                ),
                Value(lblTotal_2.Text)
            ),
            CashAmount: Value(Label6_55.Text)
        }
    );
    SubmitForm(formRecountedDeposit);
);
UpdateContext({varDialogConfirmarAgregarDeposito: false});

If(
    Self.SelectedButton.Label = "Continuar",
    Patch('CH-Tbl-DepositsRecountings', varSelectedRecountedDeposit, {RelatedDeclaredDeposit: gvarSelectedDeclaredDeposit});
    Patch('CH-Tbl-DeclaredDeposits', gvarSelectedDeclaredDeposit, {RelatedRecountedDeposit: varSelectedRecountedDeposit});
    Set(gvarSelectedDeclaredDeposit, LookUp('CH-Tbl-DeclaredDeposits', 'CH-Tbl-DeclaredDeposits'=gvarSelectedDeclaredDeposit.'CH-Tbl-DeclaredDeposits'));
    UpdateContext({varSelectedRecountedDeposit: LookUp('CH-Tbl-DepositsRecountings', 'CH-Tbl-DepositsRecounting'=varSelectedRecountedDeposit.'CH-Tbl-DepositsRecounting')});
);
UpdateContext({varDialogConfirmarEnlazarDeposito: false});

If(
    Self.SelectedButton.Label = "Continuar",
    Patch(
        'CH-Tbl-DepositsRecountings',
        varSelectedRecountedDeposit,
        {
            RelatedDeclaredDeposit: Blank(),
            BACLocalCheckAmount: First(colNewDeposit).BACLocalCheckAmount,
            OtherLocaCheckAmount: First(colNewDeposit).OtherLocaCheckAmount,
            AccountNumber: Blank()
        }
    );
    Patch(
        'CH-Tbl-DeclaredDeposits',
        gvarSelectedDeclaredDeposit,
        {RelatedRecountedDeposit: Blank()}
    );
    UpdateIf(
        colChecks,
        !IsBlank(RelatedDeclaredCheck),
        {Selected: false}
    );
    ForAll(
        Filter(
            colChecks,
            !IsBlank(RelatedDeclaredCheck) && !Selected && !IsBlank(RelatedReCounterDepositID)
        ) As DescelectedCheck,
        Patch(
            'CH-Tbl-DeclaredChecks',
            DescelectedCheck.RelatedDeclaredCheck,
            {DeclaredDepositID: Blank()}
        );
        Remove(
            'CH-Tbl-Checks',
            DescelectedCheck
        );
    );
    Clear(colRecountedMoneyDetails);
    Clear(colChecks);
    UpdateContext({varSelectedRecountedDeposit: Blank()});
    Set(
        gvarSelectedDeclaredDeposit,
        Blank()
    );

);
UpdateContext({varDialogConfirmarDesnlazarDeposito: false});

If(
    Self.SelectedButton.Label = "Continuar",
    Clear(colRecountedMoneyDetails);
    Clear(colRecountedMoneyDetails);
    ForAll(
        Filter(
            colDefinedDenominations,
            Currency = DropdownCanvas1.Selected.Value
        ) As Denomination,
        Patch(
            colRecountedMoneyDetails,
            Defaults('CH-Tbl-CountedMoneyDetails'),
            {
                DenominationType: If(
                    Denomination.Type = 'Type (CH-Tbl-MoneyDenominations)'.Billete,
                    "Billete",
                    "Moneda"
                ),
                Quantity: 0,
                Denomination: Denomination.Value
            }
        );
    );
    RemoveIf(
        colChecks,
        IsBlank(RelatedDeclaredCheck)
    );
    Reset('gal Checks');
    If(
        varSelectedRecountedDeposit.Currency = DropdownCanvas1.Selected.Value,
        ClearCollect(
            colRecounted,
            varSelectedRecountedDeposit.'CH-Tbl-CountedMoneyDetails'
        );
        ForAll(
            colRecounted As MoneyDetails,
            RemoveIf(
                colRecountedMoneyDetails,
                DenominationType = MoneyDetails.DenominationType && Denomination = MoneyDetails.Denomination
            );
            Collect(
                colRecountedMoneyDetails,
                MoneyDetails
            );
        )
    );
    Set(gvarSelectedDeclaredDeposit, Blank());
);
UpdateContext({varDialogConfirmarCambioMoneda: false});

UpdateContext({varRecountedDeposit: formRecountedDepositNew.LastSubmit});
Notify("Deposito creado");
//Updating Cash details
//Delete cash with 0 and created on details
ForAll(
    Filter(
        colRecountedMoneyDetails,
        Quantity = 0 && !IsBlank('CH-Tbl-CountedMoneyDetails')
    ) As Money,
    Remove(
        'CH-Tbl-CountedMoneyDetails',
        Money
    )
);
//Delete all the money if currency change is made
RemoveIf(
    'CH-Tbl-CountedMoneyDetails',
    varSelectedRecountedDeposit.Currency <> DropdownCanvas1.Selected.Value && RelatedDepositRecountingID.'CH-Tbl-DepositsRecounting' = varSelectedRecountedDeposit.'CH-Tbl-DepositsRecounting'
);
ForAll(
    Filter(
        colRecountedMoneyDetails,
        Quantity > 0
    ) As Money,
    Patch(
        'CH-Tbl-CountedMoneyDetails',
        Money,
        {
            RelatedDepositRecountingID: varRecountedDeposit,
            Denomination: Money.Denomination,
            DenominationType: Money.DenominationType,
            Quantity: Money.Quantity
        }
    );

);
//Update Cheques
//Desenlazar cheques enlazados
ForAll(
    Filter(
        colChecks,
        !IsBlank(RelatedDeclaredCheck) && !Selected && !IsBlank(RelatedReCounterDepositID)
    ) As DescelectedCheck,
    Patch(
        'CH-Tbl-DeclaredChecks',
        DescelectedCheck.RelatedDeclaredCheck,
        {DeclaredDepositID: Blank()}
    );
    Remove(
        'CH-Tbl-Checks',
        DescelectedCheck
    );

);
//Quitar cheques no declarados que hayan sido eliminados
ForAll(
    colDeletedChecks As DeletedCheck,
    Remove(
        'CH-Tbl-Checks',
        DeletedCheck
    );

);
ForAll(
    DropColumns(
        Filter(
            colChecks,
            IsBlank(RelatedDeclaredCheck) || Selected
        ),
        Selected,
        OrderID
    ) As Check,
    Patch(
        'CH-Tbl-Checks',
        Check,
        {
            RelatedReCounterDepositID: varRecountedDeposit,
            RelatedDeclaredCheck: Check.RelatedDeclaredCheck,
            CheckTypes: Check.CheckTypes,
            CheckCurrency: Check.CheckCurrency,
            CheckNumber: Check.CheckNumber,
            CheckAmount: Check.CheckAmount
        }
    );

);
ResetForm(Self);
NewForm(Self);
Clear(colChecks);
Clear(colRecountedMoneyDetails);
UpdateContext({varSelectedRecountedDeposit: Blank()});
Clear(colDeletedChecks);

UpdateContext(
        {
            varRecountingSession: LookUp(
                'CH-Tbl-RecountingSessions',
                Cashier.User = gvarUser.User && 'Created On' >= Today() && 'Created On' < DateAdd(
                    Today(),
                    1,
                    TimeUnit.Days
                )
            )
        }
    );

    Notify("Esta corriendo");
